import feedparser
import datetime
import sys

def digest(since=None):
    # Read the Atom feed
    feed = feedparser.parse('feeds/status.atom')
    items = []
    for entry in feed.entries:
        item = {
            'title': entry.title,
            'href': entry.link,
            'id': entry.id,
            'date': entry.updated if hasattr(entry, 'updated') else entry.published
        }
        if since is None or datetime.datetime.strptime(item['date'], '%Y-%m-%dT%H:%M:%SZ') >= since:
            items.append(item)
    return items

if __name__ == '__main__':
    if len(sys.argv) > 2:
        since = datetime.datetime.strptime(sys.argv[2], '%Y-%m-%d')
    else:
        since = None
    items = digest(since)
    for item in items:
        print(f'Title: {item['title']}
Link: {item['href']}
ID: {item['id']}
Date: {item['date']}
')

